style.css:
@-moz-document domain("roblox.com") {
/* ---------- tokens ---------- */
:root {
  --aero-sky-top:    #bfe9ff;
  --aero-sky-mid:    #7cc7ef;
  --aero-sky-deep:   #1f6fb2;
  --aero-ink:        #0d3355;
  --aero-leaf:       #7ec845;
  --aero-leaf-deep:  #3f8c1a;
  --aero-glass:      rgba(255,255,255,.55);
  --aero-glass-line: rgba(255,255,255,.85);
  --aero-shadow:     0 2px 6px rgba(9,54,92,.28);

  /* the signature: one reusable wet-gloss highlight */
  --aero-gloss: linear-gradient(
      to bottom,
      rgba(255,255,255,.85) 0%,
      rgba(255,255,255,.45) 48%,
      rgba(255,255,255,.06) 49%,
      rgba(255,255,255,.28) 100%);
}

/* ---------- sky + bubbles ---------- */
body {
  background:
    radial-gradient(circle at 18% 78%, rgba(255,255,255,.55) 0 6px, transparent 7px),
    radial-gradient(circle at 31% 40%, rgba(255,255,255,.40) 0 11px, transparent 12px),
    radial-gradient(circle at 74% 66%, rgba(255,255,255,.45) 0 8px, transparent 9px),
    radial-gradient(circle at 88% 24%, rgba(255,255,255,.30) 0 15px, transparent 16px),
    radial-gradient(circle at 52% 12%, rgba(255,255,255,.35) 0 5px, transparent 6px),
    linear-gradient(to bottom, var(--aero-sky-top) 0%, var(--aero-sky-mid) 55%, #58a9d6 100%)
    fixed;
  color: var(--aero-ink);
  font-family: "Segoe UI", Frutiger, "Frutiger Linotype", Tahoma, sans-serif !important;
}

/* the ground: a soft green band along the bottom of the viewport */
body::after {
  content: "";
  position: fixed; inset: auto 0 0 0; height: 22vh;
  background: linear-gradient(to top, rgba(88,180,50,.75), rgba(88,180,50,0));
  pointer-events: none; z-index: 0;
}
#container-main, .content { position: relative; z-index: 1; }

/* ---------- glass panels ---------- */
.section,
.container-list,
.card-item,
.game-card-container,
.people-list-container,
.rbx-tabs-horizontal + div,
.section-content {
  background: var(--aero-glass) !important;
  border: 1px solid var(--aero-glass-line) !important;
  border-radius: 14px !important;
  box-shadow: var(--aero-shadow), inset 0 1px 0 #fff !important;
  backdrop-filter: blur(6px) saturate(140%);
}

/* thin gloss cap on every panel */
.section { position: relative; overflow: hidden; }
.section::before {
  content: "";
  position: absolute; inset: 0 0 auto 0; height: 46%;
  background: var(--aero-gloss);
  border-radius: 14px 14px 40% 40% / 14px 14px 18px 18px;
  pointer-events: none;
}

/* ---------- navigation ---------- */
#navigation, .rbx-navbar-header, .navbar-universal, #header {
  background: linear-gradient(to bottom, #2b90d9 0%, #1668a8 49%, #0d4f86 50%, #1a74b4 100%) !important;
  border-bottom: 1px solid rgba(255,255,255,.6) !important;
  box-shadow: 0 3px 10px rgba(6,40,70,.45) !important;
}
#navigation a, .navbar-universal a, .rbx-navbar a {
  color: #eaf7ff !important;
  text-shadow: 0 1px 1px rgba(0,0,0,.45);
}
#navigation a:hover, .navbar-universal a:hover {
  background: rgba(255,255,255,.18) !important;
  border-radius: 8px;
}

/* ---------- pill buttons ---------- */
.btn-primary-md, .btn-primary-lg, .btn-primary-xs,
.btn-secondary-md, .btn-growth-md, .btn-control-md,
.btn-common-play-game-lg {
  position: relative;
  border-radius: 999px !important;
  border: 1px solid rgba(255,255,255,.75) !important;
  color: #fff !important;
  text-shadow: 0 1px 1px rgba(0,0,0,.35);
  box-shadow: var(--aero-shadow), inset 0 -8px 12px rgba(0,0,0,.12), inset 0 1px 0 #fff !important;
  overflow: hidden;
  transition: filter .12s ease;
}
.btn-primary-md, .btn-primary-lg, .btn-primary-xs {
  background: linear-gradient(to bottom, #63c6f5, #1a7fc4 49%, #0f6cae 50%, #37a4de) !important;
}
.btn-common-play-game-lg, .btn-growth-md {
  background: linear-gradient(to bottom, #a9e86a, var(--aero-leaf) 49%, var(--aero-leaf-deep) 50%, #6cbb35) !important;
}
.btn-primary-md::after, .btn-primary-lg::after, .btn-primary-xs::after,
.btn-growth-md::after, .btn-common-play-game-lg::after {
  content: "";
  position: absolute; inset: 1px 1px auto 1px; height: 45%;
  background: var(--aero-gloss);
  border-radius: 999px;
  pointer-events: none;
}
.btn-primary-md:hover, .btn-growth-md:hover, .btn-common-play-game-lg:hover { filter: brightness(1.12); }
.btn-primary-md:active, .btn-growth-md:active { filter: brightness(.92); }

/* ---------- type ---------- */
.font-header-1, .font-header-2, h1, h2, h3 {
  color: var(--aero-ink) !important;
  text-shadow: 0 1px 0 rgba(255,255,255,.9);
  letter-spacing: .01em;
}
.text-lead, .text-description, .text-label, p, span { color: #16405f !important; }

/* ---------- thumbnails and avatars ---------- */
.game-card-thumb-container img, .thumbnail-2d-container img, .avatar-card-image img {
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,.8);
  box-shadow: 0 2px 5px rgba(9,54,92,.3), inset 0 1px 0 #fff;
}
.game-card-container:hover { box-shadow: 0 0 0 2px #fff, 0 6px 18px rgba(9,54,92,.4) !important; }

/* ---------- inputs ---------- */
input[type="text"], input[type="search"], input[type="password"], textarea, select {
  background: rgba(255,255,255,.85) !important;
  border: 1px solid #7fb6da !important;
  border-radius: 999px !important;
  box-shadow: inset 0 2px 4px rgba(20,70,110,.25) !important;
  color: var(--aero-ink) !important;
  padding-left: 12px !important;
}
input:focus, textarea:focus {
  outline: 2px solid rgba(255,255,255,.9);
  outline-offset: 1px;
  border-color: #2b90d9 !important;
}

/* ---------- scrollbar ---------- */
::-webkit-scrollbar { width: 13px; }
::-webkit-scrollbar-track { background: rgba(255,255,255,.35); }
::-webkit-scrollbar-thumb {
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.8);
  background: linear-gradient(to bottom, #8fd7f7, #2b90d9);
}

/* ---------- accessibility ---------- */
a:focus-visible, button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
}
